/* -1. 聊天气泡整体布局与间距- */
.mes {
  position: relative;
  z-index: -1;
  background-size: 100% auto; 
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  max-width: 420px;/*💽气泡框大小*/
  margin: 200px auto 150px;/*💿次选调整第一个数值，气泡间缝大小*/
  transform: scale(1) rotate(0deg) !important;/*📼调scale括号内，加小数点1.1这样小调*/
  background-image: url('https://iili.io/fZzthba.png'); 
  background-repeat: repeat-y;
  background-position: top center;
  overflow: visible;
  border: 0 !important;
  border-width: 0 !important;
  border-style: none !important;
  border-color: transparent !important;
  outline: 0 !important;
  box-shadow: none !important; 
  padding-bottom: 0px;
}


.mes_block {
    position: relative !important;
    overflow: visible !important; 
    margin-top: 0px; 
    z-index: auto;
}

/* ========头像与头像框========= */
/* 头像容器位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: -122px !important;    /* 💽上下微调 */
    left: 263px !important;   /* 💽左右微调 */
    width: auto !important;
    height: auto !important;
    padding: 0 !important;
    margin: 0 !important;
    z-index: 3 !important;
    overflow: visible !important;
    filter: none !important;
    box-shadow: none !important;
}


/* 头像本体 */
.mesAvatarWrapper .avatar {
    width: 100px;  
    height: 100px;
    transform: scale(1.46) rotate(0deg) !important; /* 💽缩放与旋转 */
    transform-origin: center center !important;
    max-width: unset !important;
    max-height: unset !important;
    clip-path: polygon(77% 15%, 97% 35%, 97% 86%, 0 86%, 0 15%);
}

.mesAvatarWrapper .avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    box-shadow: none !important;
}

/* 头像框 */
.mesAvatarWrapper::after {
    content: '';
    position: absolute;
    top: 50% !important;   /* 💽锚点居中 */
    left: -53.1% !important;  /* 💽锚点居中 */
    width: 100% !important;
    height: 100% !important;
    transform: translate(-50%, -50%) scale(3.7) rotate(0deg) !important; 
    background-image: url('https://iili.io/fZuqt2t.png');
    background-size: contain !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    pointer-events: none;
    z-index: 4;
    filter: 
    contrast(1)      /* 对比度 */
    brightness(1)    /* 暗度*/
    saturate(1)      /* 饱和度 */
    hue-rotate(1deg)  /* 色相 */
}

/* .2.名字与时间戳 */

/* 💽名字 */
.name_text {
    position: absolute !important;
    z-index: 101;
    top: -100px !important;      /* 💽上下微调 */
    left: 35% !important;       
    transform: translateX(-50%) !important; 
    width: auto !important;
    text-align: center !important; 
    font-size: 11px !important;
    font-weight: 400 !important;
    white-space: nowrap !important;
    color: #0F3F16 !important; /* 颜色 */
    opacity: 0.9;
    -webkit-text-stroke: 0px #ffffff !important;
    paint-order: stroke fill !important;
}

.name_text::before {
    content: ''; 
    display: inline-block;
    margin-right: -5px;
    color: inherit;
    pointer-events: none;
}

.name_text::after {
    content: ''; 
    display: inline-block;
    margin-left: 0px;
    pointer-events: none;
}


/* 💽时间戳 */
.timestamp {
    position: absolute !important;
    z-index: 9;
    top: 26px !important;     /* 💽上下微调 */
    left: 150px !important;    /* 💽左右微调 */
    font-size: 11px !important;
    font-weight: 500 !important;
    white-space: nowrap !important;
    color: #fff !important;
}

.timestamp::before {
    content: '';
    display: inline-block;
    margin-right: 0px;
}

.timestamp::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 3. 三元素信息 (楼层、计时、词符) */

/* 楼层数 */
.mesIDDisplay {
    position: absolute !important;
    z-index: 9;
    top: 55px !important;   /* 💽上下微调 */
    left: -145px !important;    /* 💽左右微调 */
    width: auto !important;
    margin: 0 !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    color: #0F3F16 !important; 
    white-space: nowrap !important;
    display: inline-flex;
    align-items: center;
}

.mesIDDisplay::before {
    content: ''; 
    display: inline-block;
    margin-right: -5px;
}

.mesIDDisplay::after {
    content: '残花'; 
    display: inline-block;
    margin-left: 5px;
}

/* 回复计时 */
.mes_timer {
    position: absolute !important;
    z-index: 9;
    top: var(--element-top, 107px) !important; 
    left: var(--element-left, 240px) !important;
    transform: translateX(-50%) rotate(0deg);
    font-size: 11px !important;
    font-weight: 400 !important;
    color: #fff !important; 
    white-space: nowrap;
    cursor: default;
    opacity: 1;
}

.mes_timer::before {
    content: ''; 
    display: inline-block;
    margin-right: -2px;
}

.mes_timer::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 词符数 */
.tokenCounterDisplay {
    position: absolute !important;
    z-index: 9;
    top: -10px !important;     /* 💽上下微调 */
    left: 145px !important;    /* 💽左右微调 */
    transform: translateX(-50%) rotate(0deg);
    font-size: 10px !important;
    font-weight: 300 !important;
    color: #fff !important; 
    -webkit-text-stroke: 0.5px #ffffff !important;
    paint-order: stroke fill !important;
    white-space: nowrap;
    opacity: 1;
}

.tokenCounterDisplay::before {
    content: '';
    display: inline-block;
    margin-right: 0px;
}

.tokenCounterDisplay::after {
    content: '';
    display: inline-block;
    margin-left: 0px;
}

/* 4. 操作按钮 (小铅笔、复制等 - 平时状态) */
.mes_buttons {
    position: absolute !important;
    z-index: 9;
    top: -15px !important;      /* 💽上下位置 */
    right: 40px !important;    /* 💽左右位置 */
    color: #fff;
    display: flex !important;             
    flex-direction: row;       
    align-items: center;       
    gap: 0px;                  /* 间距*/
    margin: 0 !important;
    padding: 0 !important;
    opacity: 0;           
    transition: opacity 0.2s ease; 
}

.mes:hover .mes_buttons {
    opacity: 1;
}

.mes_buttons > div {
    margin: 0 !important;
    padding: 0 1px !important; 
}

.mes_buttons[style*="display: none"],
.mes_buttons[style*="display:none"] {
    display: none !important;
    opacity: 0 !important;
}


/* 编辑状态菜单 */
.mes_edit_buttons {
    position: absolute !important;
    z-index: 15;
    top: -15px !important;      
    right: 40px !important;
    flex-direction: row;
    align-items: center;
    gap: 0px;        
    opacity: 1 !important; 
    display: none; 
}

/* 去除编辑、删除、重生成等按钮的阴影和发光 */
.mes_buttons div, 
.mes_edit,
.mes_text_paste {
    text-shadow: none !important;  /* 去除字体发光/阴影 */
    box-shadow: none !important;   /* 去除盒子边框阴影 */
    filter: none !important;       /* 去除滤镜产生的投影 */
}

.mes_buttons div:hover,
.mes_edit:hover {
    text-shadow: none !important;
}



/* -5. 文本框主体 (Text)- */
/* --- User (用户) 文本框 --- */
.mes[is_user="true"] .mes_text {
    padding-top: 5px !important;    /* 💽加大数值=文字下移，减小=文字上移 */
    margin-top: -10px !important;/*💿同上*/
    padding-bottom: 15px !important; /* 💽底部留白 */
    padding-left: 35px !important;   /* 💽左侧留白 */
    padding-right: 40px !important;  /* 💽右侧留白 */
    min-height: 0px !important;  
    text-align: justify; 
}

/* --- Char (角色) 文本框 --- */
.mes[is_user="false"] .mes_text {
    padding-top: -80px !important;    /* 💽加大数值=文字下移，减小=文字上移 */
    margin-top: -40px !important;/*💿同上*/
    padding-bottom: 5px !important; /* 💽底部留白 */
    padding-left: 30px !important;   /* 💽左侧留白 */
    padding-right: 40px !important; /* 💽右侧留白 */
    min-height: 0px !important;
    text-align: justify;
}


/*杂七杂八的东西*/
.mesIDDisplay, .mes_timer, .tokenCounterDisplay, .name_text, .timestamp {
    position: absolute !important;
    z-index: 9;
    width: auto !important;
    white-space: nowrap !important;
    pointer-events: none; 
}

/* --- 修复：右滑生成时名字被裁切消失 --- */
.slick-list, 
.slick-track,
.mes_text_container,
.mes-group-container {
    overflow: visible !important;
}



