.mes_edit_buttons,
.mes_buttons *, 
.mes_edit_buttons *,
.mes_buttons div, 
.mes_edit_buttons button {
    text-shadow: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
}

.mes_buttons,
.mes_edit_buttons,
.mes_buttons > div,
.mes_edit_buttons button {
    opacity: 1 !important;
    visibility: visible !important;
    transition: none !important;
