/* 底栏容器 */
#send_form {
    display: block !important; 
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    position: relative !important;
    z-index: 50 !important;
    background: transparent !important;
    border: none !important;
    padding: 8px 8px 10px 8px !important; 
    overflow: visible !important;
    height: auto !important; 
}

#send_form::before {
    content: "";
    position: absolute;
    top: -10px; left: 0; right: 0; bottom: 0;
    background-image: url('https://iili.io/fZimSzx.png') !important;
    background-size: cover !important; 
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-color: rgba(13, 16, 21, 0) !important; 
    backdrop-filter: blur(0px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    z-index: -1;
    pointer-events: none;
}

/* 输入框本体 */
#send_textarea {
    clip-path: none !important; 
    box-sizing: border-box !important;
    line-height: 1.6 !important;
    transition: background-color 0.2s ease, box-shadow 0.2s ease !important;
    resize: none !important;      
    background-color: rgba(164, 179, 164, 0) !important;
    color: rgba(164, 179, 164, 1) !important; 
    border: 1px solid transparent !important; 
    box-shadow: inset 1px 2px 6px rgba(164, 179, 164, 0.5) !important;
    border-radius: 8px !important;    
    padding: 4px 8px !important; /* 减少上下padding从8px到4px */
    margin: 0 !important;
    width: 100% !important;
    max-height: 80px !important; /* 减少最大高度从200px到150px */
    overflow-y: auto !important;
    min-height: 20px !important; /* 减少最小高度从40px到30px */
}

/* 交互状态：聚焦时 */
#send_textarea:focus {
    background-color: rgba(164, 179, 164, 0) !important;
    box-shadow: inset 1px 2px 4px rgba(164, 179, 164, 0.8) !important;
    border-color: transparent !important;
}


/* 提示词样式 */
#send_textarea::placeholder {
    color: rgba(255, 255, 255, 0.5) !important;
}


/*底栏图标*/
#send_form [class*="fa-"]::before {
  content: '' !important;
  display: inline-block;
  width: 26px; /* 图片宽度 */
  height: 26px; /* 图片高度 */
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  vertical-align: middle;
}

/* 菜单 */
#options_button::before {
